package local.snapexplorer.mobile;
import android.app.*;import android.content.*;import android.database.Cursor;import android.os.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;
/** Synthetic, disposable-emulator-only regression for dual-format large chats. */
public final class LargeChatSmoke extends Instrumentation {
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle result=new Bundle();try{run();result.putString("stream","PASS 10 large-chat import and repair checks\n");finish(Activity.RESULT_OK,result);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("stream",s.toString());finish(Activity.RESULT_CANCELED,result);}}
 private static String body(int i,int count,String padding){return (i>=count-2?"Genuine repeat":"Message "+i)+" "+padding;}
 private void run()throws Exception{
  Context c=getTargetContext();File file=new File(c.getCacheDir(),"large-dual-format.zip");int count=5000;String padding=String.join("",Collections.nCopies(300,"x"));
  try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(file))){zip.putNextEntry(new ZipEntry("json/chat_history.json"));Writer w=new OutputStreamWriter(zip,StandardCharsets.UTF_8);w.write("{\"large\":[");for(int i=0;i<count;i++){if(i>0)w.write(',');w.write("{\"From\":\"Alex\",\"Created\":\"2026-01-01 12:00:00 UTC\",\"Content\":\""+body(i,count,padding)+"\",\"Media Type\":\"text\"}");}w.write("]}");w.flush();zip.closeEntry();zip.putNextEntry(new ZipEntry("html/chat_history/subpage_large.html"));w=new OutputStreamWriter(zip,StandardCharsets.UTF_8);w.write("<h1>Chat History with large</h1><div class=rightpanel>");for(int i=0;i<count;i++)w.write("<div><h4>Alex</h4><span>TEXT</span><p>"+body(i,count,padding)+"</p><h6>2026-01-01 12:00:00 UTC</h6></div>");w.write("</div>");w.flush();zip.closeEntry();}
  try(java.util.zip.ZipFile check=new java.util.zip.ZipFile(file)){if(check.getEntry("json/chat_history.json").getSize()<=1024*1024||check.getEntry("html/chat_history/subpage_large.html").getSize()<=1024*1024)throw new AssertionError("Both fixtures must use streaming paths");}
  ChatRepository repo=new ChatRepository(c);repo.importArchives(Collections.singletonList(new ChatRepository.Input(file,"Large synthetic paired formats",false)),true,(a,b)->{});long actual;try(Cursor cursor=repo.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM messages WHERE chat='large'",null)){cursor.moveToFirst();actual=cursor.getLong(0);}if(actual!=count)throw new AssertionError("Every large-chat message must occur once; expected "+count+", actual "+actual);
  repo.getWritableDatabase().execSQL("INSERT INTO messages(chat,sender,body,kind,date,epoch,media_refs,reply_to,external_id,own) SELECT chat,sender,body,upper(kind),date,epoch,media_refs,reply_to,external_id,own FROM messages WHERE chat='large'");
  ChatRepeatRepair.Result repaired=ChatRepeatRepair.run(c,repo,"large","large");if(repaired.htmlText<=0||repaired.jsonText<=0||repaired.pairedKeys<=0||repaired.matchedKeys<=0)throw new AssertionError("Local diagnostics must expose count-only matching evidence");if(repaired.raw!=count*2||repaired.hidden!=count||repaired.visible!=count)throw new AssertionError("Existing doubled conversation repair: raw="+repaired.raw+",hidden="+repaired.hidden+",visible="+repaired.visible);
  try(Cursor cursor=repo.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM messages",null)){cursor.moveToFirst();if(cursor.getLong(0)!=count*2)throw new AssertionError("Repair must preserve original rows");}
  if(repo.searchCount("large","Message")!=count-2)throw new AssertionError("Search must exclude verified duplicate aliases");
  try(Cursor cursor=repo.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM messages m WHERE m.body LIKE 'Genuine repeat%' AND "+DatabaseQueries.VISIBLE,null)){cursor.moveToFirst();if(cursor.getLong(0)!=2)throw new AssertionError("True repeated sends must survive repair");}
  ChatRepeatRepair.undo(repo,"large");try(Cursor cursor=repo.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM messages m WHERE "+DatabaseQueries.VISIBLE,null)){cursor.moveToFirst();if(cursor.getLong(0)!=count*2)throw new AssertionError("Repair must be reversible");}
  File folder=new File(c.getCacheDir(),"large-nested-folder.zip");try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(folder))){for(String name:new String[]{"part-1.zip","copy-of-part-1.zip"}){zip.putNextEntry(new ZipEntry(name));try(InputStream in=new FileInputStream(file)){byte[] buffer=new byte[65536];int n;while((n=in.read(buffer))!=-1)zip.write(buffer,0,n);}zip.closeEntry();}}
  repo.importArchives(Collections.singletonList(new ChatRepository.Input(folder,"Synthetic folder with repeated ZIP parts",false)),true,(a,b)->{});try(Cursor cursor=repo.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM messages",null)){cursor.moveToFirst();if(cursor.getLong(0)!=count)throw new AssertionError("Repeated nested ZIP parts must not double the conversation");}
  repo.getWritableDatabase().execSQL("INSERT INTO messages(chat,sender,body,kind,date,epoch,media_refs,reply_to,external_id,own) SELECT chat,sender,body,upper(kind),date,epoch,media_refs,reply_to,external_id,own FROM messages WHERE chat='large'");
  repaired=ChatRepeatRepair.run(c,repo,"large","large");if(repaired.hidden!=count||repaired.visible!=count||repaired.html!=2||repaired.json!=2)throw new AssertionError("Folder ZIP repair must inspect both nested parts without copying media");repo.close();
 }
}
